// Agent server fixture entry `env-probe`: input -> probe (tool) -> final.
//
// The tool reports what the project's code can see: the deploy-time variable SERVE_FIXTURE_GREETING, whether
// the server's own bearer token (OMEGA_SERVE_TOKEN) leaked into the worker's environment (it must not), and,
// on Linux, every OMEGA_SERVE_TOKEN value readable from any process's starting environment in /proc (the
// server's included). It never reports a value itself: only whether it is a digest and the value's SHA-256.
import { createHash } from "node:crypto";
import { readdirSync, readFileSync } from "node:fs";
import { createOmega, defineWorkflow, InMemoryTraceSink, inputStep, outputStep, tool, toolStep } from "@omega/core";

const VARIABLE = "OMEGA_SERVE_TOKEN=";

/** null where there is no /proc (not Linux). */
function serverTokenInProc(): Array<{ pid: number; isDigest: boolean; sha256: string }> | null {
  let pids: string[];
  try { pids = readdirSync("/proc").filter((name) => /^\d+$/.test(name)); } catch { return null; }
  const found: Array<{ pid: number; isDigest: boolean; sha256: string }> = [];
  for (const pid of pids) {
    let environ: string;
    try { environ = readFileSync(`/proc/${pid}/environ`, "utf8"); } catch { continue; }
    for (const entry of environ.split("\0")) {
      if (!entry.startsWith(VARIABLE)) continue;
      const value = entry.slice(VARIABLE.length);
      found.push({ pid: Number(pid), isDigest: /^sha256:[0-9a-f]{64}$/i.test(value), sha256: createHash("sha256").update(value, "utf8").digest("hex") });
    }
  }
  return found;
}

export const probeEnv = tool({
  name: "probe_env",
  description: "Report the deploy-time variables this process sees.",
  inputSchema: {},
  execute: async () => ({
    greeting: process.env.SERVE_FIXTURE_GREETING ?? null,
    secretSet: process.env.SERVE_FIXTURE_SECRET !== undefined,
    serverTokenVisible: process.env.OMEGA_SERVE_TOKEN !== undefined,
    serverTokenInProc: serverTokenInProc()
  })
});

export const workflow = defineWorkflow({
  id: "env-probe",
  name: "Env probe",
  steps: [inputStep("input"), toolStep("probe", probeEnv), outputStep("final")]
});

export const app = createOmega({ trace: new InMemoryTraceSink() });

