// Agent server fixture entry `greet`: input -> greeter (agent) -> final.
//
// The model is a function model from @omega/core/testing: deterministic, keyless, it never leaves the machine.
// It answers "Hello, <what it was asked>" so a run through `omega serve` shows the input reached the agent.
import { agent, agentStep, createOmega, defineWorkflow, InMemoryTraceSink, inputStep, outputStep } from "@omega/core";
import { functionModel } from "@omega/core/testing";

const MODEL_ID = "serve-fixture-greeter";

const model = functionModel({
  id: MODEL_ID,
  respond: (request) => {
    const asked = [...request.messages].reverse().find((message) => message.role === "user");
    const text = typeof asked?.content === "string" ? asked.content : JSON.stringify(asked?.content ?? "");
    return `Hello, ${text}`;
  }
});

export const greeter = agent({
  id: "greeter",
  name: "Greeter",
  model: MODEL_ID,
  instructions: "Greet whoever the input names.",
  memory: false
});

export const workflow = defineWorkflow({
  id: "greet",
  name: "Greet",
  steps: [inputStep("input"), agentStep("greeter", greeter), outputStep("final")]
});

export const app = createOmega({ providers: [model], trace: new InMemoryTraceSink() });

