// Agent server fixture entry `wait`: input -> pause (tool) -> final.
//
// The tool waits `ms` milliseconds (at most 10 s) and returns, so a test can hold a run in flight while the
// server drains: the run finishes inside the grace period and no new run is accepted meanwhile. When the
// deployment sets SERVE_FIXTURE_WAIT_FOR_DRAIN to the server's /health URL, the tool first waits (up to
// 5 minutes) until that answers "draining", so the run is certainly in flight when a redeploy stops the
// server, and it reports whether it saw the drain.
import { createOmega, defineWorkflow, InMemoryTraceSink, inputStep, outputStep, tool, toolStep } from "@omega/core";

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

async function drainSeen(health: string): Promise<boolean> {
  const deadline = Date.now() + 300_000;
  while (Date.now() < deadline) {
    try {
      const response = await fetch(health, { signal: AbortSignal.timeout(2_000) });
      const body = await response.json() as { status?: string };
      if (response.status === 503 && body.status === "draining") return true;
    } catch { /* not answering yet: keep polling */ }
    await sleep(100);
  }
  return false;
}

export const pause = tool({
  name: "pause",
  description: "Wait for a number of milliseconds, then return.",
  inputSchema: { ms: "number" },
  execute: async ({ ms }: { ms: number }) => {
    const waited = Math.max(0, Math.min(Number(ms) || 0, 10_000));
    const health = process.env.SERVE_FIXTURE_WAIT_FOR_DRAIN;
    const sawDrain = health === undefined || health === "" ? undefined : await drainSeen(health);
    await sleep(waited);
    return sawDrain === undefined ? { waited } : { waited, sawDrain };
  }
});

export const workflow = defineWorkflow({
  id: "wait",
  name: "Wait",
  steps: [inputStep("input"), toolStep("pause", pause, { arguments: { ms: 1500 } }), outputStep("final")]
});

export const app = createOmega({ trace: new InMemoryTraceSink() });
